1	/**
2	 * Sweep harness: dump a test server's connection details + port forwards.
3	 * Writes the root password to <scratch>/pw-<serverId> (mode 600) and prints
4	 * everything else as JSON — the password is NEVER printed.
5	 * Usage: npx tsx info.ts <serverId>
6	 */
7	import { db } from "/opt/nxeon/lib/db";
8	import { decryptSecret } from "/opt/nxeon/lib/crypto-box";
9	import { GAME_PORT, type GameFamily } from "/opt/nxeon/lib/games";
10	import { writeFileSync, chmodSync } from "node:fs";
11	
12	const SCRATCH = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep";
13	
14	(async () => {
15	  const serverId = process.argv[2];
16	  if (!serverId) throw new Error("usage: info.ts <serverId>");
17	  const s = await db.server.findUnique({
18	    where: { id: serverId },
19	    select: {
20	      id: true,
21	      hostname: true,
22	      status: true,
23	      vmid: true,
24	      ipAddress: true,
25	      sshPort: true,
26	      rootPassword: true,
27	      rootPasswordEnc: true,
28	      gameVariant: true,
29	      gameConfig: true,
30	      dedicatedIp: { select: { address: true } },
31	      node: { select: { publicIp: true, name: true, pveNode: true, isPrimary: true } },
32	      gamePlan: { select: { gameFamily: true, name: true } },
33	      osTemplate: { select: { family: true, name: true } },
34	      plan: { select: { ramMB: true, cpuCores: true, diskGB: true } },
35	    },
36	  });
37	  if (!s) throw new Error(`server ${serverId} not found`);
38	
39	  const pw = s.rootPassword ?? decryptSecret(s.rootPasswordEnc);
40	  const pwFile = `${SCRATCH}/pw-${serverId}`;
41	  if (pw) {
42	    writeFileSync(pwFile, pw, "utf8");
43	    chmodSync(pwFile, 0o600);
44	  }
45	
46	  const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family) as GameFamily | undefined;
47	  const gp = family ? GAME_PORT[family] : undefined;
48	
49	  const forwards = await db.portForward.findMany({
50	    where: { serverId },
51	    select: { id: true, publicPort: true, guestPort: true, protocol: true },
52	    orderBy: { guestPort: "asc" },
53	  });
54	
55	  console.log(
56	    JSON.stringify(
57	      {
58	        id: s.id,
59	        hostname: s.hostname,
60	        status: s.status,
61	        vmid: s.vmid,
62	        privateIp: s.ipAddress,
63	        sshPort: s.sshPort,
64	        dedicatedIp: s.dedicatedIp?.address ?? null,
65	        node: s.node,
66	        family,
67	        gamePlan: s.gamePlan?.name,
68	        plan: s.plan,
69	        gamePort: gp,
70	        gameVariant: s.gameVariant,
71	        gameConfig: s.gameConfig,
72	        forwards,
73	        pwFile: pw ? pwFile : null,
74	        gamePortForward: gp ? forwards.find((f) => f.guestPort === gp.port && f.protocol === gp.protocol) ?? null : null,
75	      },
76	      null,
77	      2
78	    )
79	  );
80	  await db.$disconnect();
81	})().catch((e) => {
82	  console.error(e);
83	  process.exit(1);
84	});
