18	
19	  const s = await db.server.findUnique({
20	    where: { id: serverId },
21	    select: {
22	      id: true,
23	      hostname: true,
24	      rootPassword: true,
25	      rootPasswordEnc: true,
26	      sshPort: true,
27	      dedicatedIp: { select: { address: true } },
28	      node: { select: { publicIp: true } },
29	      gamePlan: { select: { gameFamily: true } },
30	      osTemplate: { select: { family: true } },
