35	  if (!family) throw new Error("not a game server");
36	
37	  console.log(`[apply] family=${family} values=${JSON.stringify(values)}`);
38	  const outcome = await applyRealConfig(s as any, family, values);
39	  console.log("[apply] outcome:", JSON.stringify(outcome, null, 2));
40	  await db.$disconnect();
