import { db } from "/opt/nxeon/lib/db";
const fixes = [
  { id: "cmti0nxbr0005hlbqa1jfuubs", fam: "tf2" },
  { id: "cmti0pvql0001hlscvgh24z5k", fam: "squad" },
  { id: "cmti0qk0n0000hly4yg5rnkiz", fam: "mordhau" },
];
(async () => {
  for (const f of fixes) {
    const t = await db.osTemplate.findUnique({ where: { id: f.id }, select: { id: true, name: true, setupScript: true } });
    if (!t?.setupScript) { console.log(`${f.fam}: NOT FOUND`); continue; }
    const needle = `mkdir -p /opt/${f.fam} && docker run`;
    const repl = `mkdir -p /opt/${f.fam} && chown -R 1000:1000 /opt/${f.fam} && docker run`;
    if (t.setupScript.includes(`chown -R 1000:1000 /opt/${f.fam}`)) { console.log(`${f.fam}: already fixed, skipping`); continue; }
    if (!t.setupScript.includes(needle)) { console.log(`${f.fam}: NEEDLE NOT FOUND — live row differs:\n${t.setupScript}`); continue; }
    const updated = t.setupScript.replace(needle, repl);
    await db.osTemplate.update({ where: { id: f.id }, data: { setupScript: updated } });
    console.log(`${f.fam}: UPDATED (${t.name})`);
  }
  await db.$disconnect();
})().catch(e => { console.error(e); process.exit(1); });
EOF
