import { db } from "/opt/nxeon/lib/db";
const fams = ["arkasa","sdtd","icarus","squad","theisle","spaceengineers","eco","empyrion","soulmask","enshrouded","sonsoftheforest","mordhau","tf2"];
(async () => {
  for (const f of fams) {
